import{_ as t,o as n,c as s,ag as r}from"./chunks/framework.W-j76G-U.js";const m=JSON.parse(`{"title":"Mémo du module 0","description":"","frontmatter":{},"headers":[],"relativePath":"handout-01-memo.md","filePath":"handout-01-memo.md","handout":{"fichier":"handout-01-memo.md","markdown":"# Handout — Mémo du module 0\\n\\n**Bootcamp AI-Driven Development · Module 0 · Zenika · fiche mémo**\\n\\nLes notions du module, dans l'ordre du deck : la mécanique d'un LLM, le contexte, les embeddings et le RAG, le prompt structuré, puis les outils Claude et leurs règles d'usage.\\n\\n> **Takeaway** : un contexte clair + des instructions précises + des données fiables = une IA utile et de confiance.\\n\\n## Objectifs du bootcamp\\n\\n1. **Comprendre la mécanique d'un LLM** (tokens, probabilités, attention, context window) pour prompter plus finement et diagnostiquer les erreurs.\\n2. **Utiliser Claude au quotidien** dans ses versions chat, Projects et Cowork, en choisissant la bonne selon le besoin.\\n3. **Identifier les limites et poser les rails** : hallucinations, coût des tokens, données sensibles, Shadow AI, Zero-Data Retention, RAG, validation DSI.\\n4. **Manipuler, pas seulement écouter**, à travers plusieurs labs : Project, tâche récurrente, Cowork.\\n\\n## 1. Un domaine en plein essor\\n\\n### Les domaines de l'IA\\n\\n| Domaine                     | En une phrase                                                                                  |\\n| --------------------------- | ---------------------------------------------------------------------------------------------- |\\n| Intelligence Artificielle   | Automatisation informatisée de tâches habituellement réalisées par des humains                 |\\n| Machine Learning            | Un algorithme « apprend » à partir de données (Markov, régressions, classification de contenu) |\\n| Deep Learning               | Apprentissage par réseaux de neurones, volumineux et coûteux                                   |\\n| GenAI, LLM                  | Inclus dans le Deep Learning : les LLM sont une forme de GenAI                                 |\\n| Natural Language Processing | Reconnaissance du langage naturel, recoupe ces domaines                                        |\\n\\n### Mécanique des LLM : tokens, probabilités, température\\n\\n- Un LLM découpe le texte en **tokens** (~0,75 mot en français, unité de mémoire et de facturation) et prédit, à chaque étape, le token suivant le plus **probable**.\\n- La **température** règle le degré d'aléa de ce choix : basse pour le code, haute pour la créativité. Le **top-p** restreint le choix aux p % de masse de probabilité.\\n- Le LLM ne comprend pas au sens humain : il prédit le prochain token.\\n\\n> **Conséquence pratique** : deux prompts identiques peuvent donner deux réponses différentes. C'est une fonctionnalité, pas un bug.\\n\\n### La mémoire des LLM\\n\\nLa « mémoire » d'un assistant est une **répétition dans le prompt** : les préférences sont stockées puis réinjectées au début de chaque requête par un prompt système invisible. Les poids et l'architecture du LLM restent strictement identiques.\\n\\n### Mémoire de travail : contexte, compression et lost-in-the-middle\\n\\n| Notion                  | Ce qu'il faut savoir                                                                                                                                                                       |\\n| ----------------------- | ------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------ |\\n| **Context Window**      | Quantité de tokens vue en une requête : prompt + historique + pièces jointes + réponse. Claude Sonnet 4.6 va jusqu'à 1M tokens, mais précision et coût se dégradent bien avant ce plafond. |\\n| **Context Compression** | Quand la fenêtre sature (longue session Claude Code, Cowork…), les anciens échanges sont résumés automatiquement. On garde l'essentiel, on perd les détails.                               |\\n| **Lost in the middle**  | L'attention n'est pas uniforme : le modèle retient mieux le début et la fin (courbe en U).                                                                                                 |\\n\\nBonnes pratiques :\\n\\n- Instructions critiques **au début ET rappelées à la fin** du prompt.\\n- Documents : les plus importants en premier.\\n- Découper les longues missions en étapes courtes.\\n- Sur un travail long : « résume ce qu'on a fait, et continue ».\\n\\n### Agentique\\n\\nL'outil (le programme autour du LLM) reçoit la requête, signale au LLM les agents disponibles (recherche…), exécute les appels demandés et renvoie les résultats au LLM : **plusieurs requêtes successives** pour une seule question. Trois familles d'accès : RAG et données locales, outils via **MCP**, réalisation d'actions.\\n\\n### Embeddings et RAG\\n\\n- **Embeddings** : un texte est projeté en **vecteur numérique** dans un espace à plusieurs centaines de dimensions. Deux textes proches par le sens se retrouvent proches dans l'espace, même sans mots communs : « bug en prod » ≈ « incident critique » ≈ « panne système ».\\n- **RAG** (Retrieval-Augmented Generation) : répondre à partir de **vos documents** sans les avoir appris.\\n\\n| Étape           | Ce qui se passe                                                                                    |\\n| --------------- | -------------------------------------------------------------------------------------------------- |\\n| 1. Indexation   | Les documents sont découpés en chunks, transformés en embeddings, rangés dans une base vectorielle |\\n| 2. Retrieval    | Pour une question, on récupère les chunks les plus proches sémantiquement                          |\\n| 3. Augmentation | Les chunks retrouvés sont injectés dans le prompt comme contexte                                   |\\n\\n> C'est la parade n°1 contre les **hallucinations**. Claude : les Projects font du RAG léger automatiquement ; au-delà (10k+ docs), un connecteur MCP vers une vector DB.\\n\\n### L'écosystème et les règles d'utilisation\\n\\n- **Assistants bureautique** (intégrés aux applications), **assistants de dév** (Dev / Sec / Ops), **modèles et Cloud** (on-prem ou via des providers).\\n- Toujours utiliser une IA générative **contractualisée** par votre entreprise : pas de réutilisation des données pour l'entraînement (**Zero-Data Retention**) et confidentialité garantie. Pour tout autre outil : demander à la **DSI**.\\n- **Shadow AI** : un outil non contractualisé expose vos données à leur réutilisation.\\n- **Nos postures comptent** : individu → équipe → entreprise ; l'humain reste au centre ; une utilisation à bon escient, pas masquée, critique.\\n\\n## 2. L'art du prompt avec Claude\\n\\n### Les réglages de Claude\\n\\n- **Choisir le modèle** (menu en haut du chat) : Opus pour raisonner, Sonnet par défaut, Haiku pour aller vite.\\n- **Activer des capacités** : recherche web, exécution de code, lecture de fichiers joints (PDF, xlsx, images), connecteurs MCP (Drive, Slack, Asana…), génération d'Artifacts.\\n- **Ranger les conversations par Projects** : un historique + des fichiers + une instruction persistante.\\n- Garder en tête le **coût** et la **sobriété**.\\n\\n### Le prompt structuré\\n\\n| Élément      | Exemple                                                                                   |\\n| ------------ | ----------------------------------------------------------------------------------------- |\\n| **Persona**  | « Tu es un expert commercial en IT… »                                                     |\\n| **Tâche**    | « Tu dois produire une trame de réponse pour cet appel d'offre… »                         |\\n| **Format**   | « …au format Markdown, ton professionnel, sans réexpliquer les mots de l'appel d'offre… » |\\n| **Contexte** | le client, l'évènement, le mail contenant…                                                |\\n\\n> **Style** : Claude abuse du gras et des listes. Utiliser des **balises XML** (\`<contexte>\`, \`<tache>\`, \`<exemple>\`) pour isoler proprement les blocs du prompt.\\n\\n### Styles et Projects\\n\\n- **Styles** : ajuster le ton et le format (concis, formel, explicatif…), présets ou personnalisés.\\n- **Projects** : un espace de travail persistant (documents de référence, instructions, historique), partageable au sein d'une **Team Anthropic**.\\n\\n## 3. Outils, usages et mise en pratique\\n\\n| Outil                       | Ce qu'il fait                                                                                                                                           |\\n| --------------------------- | ------------------------------------------------------------------------------------------------------------------------------------------------------- |\\n| **Artefacts**               | Un livrable (document, tableau, page HTML, mini-app) ouvert dans un panneau à droite : édition itérative, export Word / Excel / PDF / code, persistance |\\n| **Claude Opus 4.7**         | Le raisonneur profond : tâches complexes, analyses longues. Plus lent, plus cher                                                                        |\\n| **Claude Sonnet 4.6**       | Le couteau suisse, par défaut : 90 % des usages                                                                                                         |\\n| **Claude Haiku 4.5**        | Le rapide : tâches simples et volumineuses. Quasi-instantané, très bon marché                                                                           |\\n| **Connecteurs MCP**         | Protocole standard pour lire / écrire dans un outil externe (Drive, Slack, Asana, Jira, GitHub…)                                                        |\\n| **Claude in Chrome** (beta) | Pilote vos onglets : formulaire, extraction, navigation                                                                                                 |\\n| **Claude in Excel** (beta)  | Agent tableur : nettoyer, formules, rapport                                                                                                             |\\n| **Cowork**                  | Agent de bureau avec accès contrôlé à un dossier local et au navigateur, pour les profils non techniques                                                |\\n| **Claude Code**             | Agent dans le terminal qui pilote un dépôt comme un développeur, pour les profils tech                                                                  |\\n\\n- **Pensée adaptative** : sur Opus et Sonnet, un toggle laisse Claude « réfléchir avant de répondre ».\\n- **Skill** : un dossier qui emballe un savoir-faire reproductible, un \`SKILL.md\` (mode d'emploi) + des fichiers de support, chargé **automatiquement** quand il correspond à la demande. Structure minimale : un nom + une description (quand l'activer), un \`SKILL.md\` (étapes, règles, pièges), en option des templates / checklists.\\n- **Project vs Skill** : un Project porte un **contexte** (« tout sur le client X »), une Skill porte une **compétence** (« comment rédiger un CR chez nous »). Les deux se combinent.\\n- **Cowork vs chat** : Cowork a les mains dans vos fichiers et vos applis ; le chat se limite aux pièces jointes uploadées.\\n- **Claude Code** : naviguer dans un dépôt, écrire du code sur plusieurs fichiers, lancer les tests, interagir avec Git, ouvrir une PR, appeler des MCP, charger des Skills, travailler en **mode plan** ou en exécution directe.\\n\\n> Chaque intégration doit être validée par la **DSI** : pas de données client sans feu vert.\\n\\n## 4. Synthèse : les 4 rails d'une IA utile\\n\\n| Rail                   | Ce qu'on fait                                                                                                         |\\n| ---------------------- | --------------------------------------------------------------------------------------------------------------------- |\\n| **Contexte**           | Projects pour persister, pièces jointes pour ponctuel, RAG pour la masse                                              |\\n| **Instructions**       | Persona, Tâche, Format, Contexte. Balises XML pour structurer. Critiques en haut et en bas du prompt                  |\\n| **Modèle et réglages** | Haiku pour la vitesse, Sonnet par défaut, Opus pour raisonner. Température basse pour le code, haute pour la créa     |\\n| **Vérification**       | Citations (RAG), relire le diff (Claude Code), ne jamais oublier l'hallucination. Règle DSI sur les données sensibles |\\n\\n> L'écosystème change constamment : le plus important est de **continuer à pratiquer**.\\n"}}`),o={name:"handout-01-memo.md"};function a(i,e,u,l,d,c){return n(),s("div",null,[...e[0]||(e[0]=[r('<p class="zh-type">fiche mémo</p><h1 id="handout-memo-du-module-0" tabindex="-1">Mémo du module 0 <a class="header-anchor" href="#handout-memo-du-module-0" aria-label="Permalink to &quot;Handout — Mémo du module 0&quot;">​</a></h1><p>Les notions du module, dans l’ordre du deck : la mécanique d’un LLM, le contexte, les embeddings et le RAG, le prompt structuré, puis les outils Claude et leurs règles d’usage.</p><blockquote><p><strong>Takeaway</strong> : un contexte clair + des instructions précises + des données fiables = une IA utile et de confiance.</p></blockquote><h2 id="objectifs-du-bootcamp" tabindex="-1">Objectifs du bootcamp <a class="header-anchor" href="#objectifs-du-bootcamp" aria-label="Permalink to &quot;Objectifs du bootcamp&quot;">​</a></h2><ol><li><strong>Comprendre la mécanique d’un LLM</strong> (tokens, probabilités, attention, context window) pour prompter plus finement et diagnostiquer les erreurs.</li><li><strong>Utiliser Claude au quotidien</strong> dans ses versions chat, Projects et Cowork, en choisissant la bonne selon le besoin.</li><li><strong>Identifier les limites et poser les rails</strong> : hallucinations, coût des tokens, données sensibles, Shadow AI, Zero-Data Retention, RAG, validation DSI.</li><li><strong>Manipuler, pas seulement écouter</strong>, à travers plusieurs labs : Project, tâche récurrente, Cowork.</li></ol><h2 id="1-un-domaine-en-plein-essor" tabindex="-1">1. Un domaine en plein essor <a class="header-anchor" href="#1-un-domaine-en-plein-essor" aria-label="Permalink to &quot;1. Un domaine en plein essor&quot;">​</a></h2><h3 id="les-domaines-de-l-ia" tabindex="-1">Les domaines de l’IA <a class="header-anchor" href="#les-domaines-de-l-ia" aria-label="Permalink to &quot;Les domaines de l&#39;IA&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Domaine</th><th>En une phrase</th></tr></thead><tbody><tr><td>Intelligence Artificielle</td><td>Automatisation informatisée de tâches habituellement réalisées par des humains</td></tr><tr><td>Machine Learning</td><td>Un algorithme « apprend » à partir de données (Markov, régressions, classification de contenu)</td></tr><tr><td>Deep Learning</td><td>Apprentissage par réseaux de neurones, volumineux et coûteux</td></tr><tr><td>GenAI, LLM</td><td>Inclus dans le Deep Learning : les LLM sont une forme de GenAI</td></tr><tr><td>Natural Language Processing</td><td>Reconnaissance du langage naturel, recoupe ces domaines</td></tr></tbody></table><h3 id="mecanique-des-llm-tokens-probabilites-temperature" tabindex="-1">Mécanique des LLM : tokens, probabilités, température <a class="header-anchor" href="#mecanique-des-llm-tokens-probabilites-temperature" aria-label="Permalink to &quot;Mécanique des LLM : tokens, probabilités, température&quot;">​</a></h3><ul><li>Un LLM découpe le texte en <strong>tokens</strong> (~0,75 mot en français, unité de mémoire et de facturation) et prédit, à chaque étape, le token suivant le plus <strong>probable</strong>.</li><li>La <strong>température</strong> règle le degré d’aléa de ce choix : basse pour le code, haute pour la créativité. Le <strong>top-p</strong> restreint le choix aux p % de masse de probabilité.</li><li>Le LLM ne comprend pas au sens humain : il prédit le prochain token.</li></ul><blockquote><p><strong>Conséquence pratique</strong> : deux prompts identiques peuvent donner deux réponses différentes. C’est une fonctionnalité, pas un bug.</p></blockquote><h3 id="la-memoire-des-llm" tabindex="-1">La mémoire des LLM <a class="header-anchor" href="#la-memoire-des-llm" aria-label="Permalink to &quot;La mémoire des LLM&quot;">​</a></h3><p>La « mémoire » d’un assistant est une <strong>répétition dans le prompt</strong> : les préférences sont stockées puis réinjectées au début de chaque requête par un prompt système invisible. Les poids et l’architecture du LLM restent strictement identiques.</p><h3 id="memoire-de-travail-contexte-compression-et-lost-in-the-middle" tabindex="-1">Mémoire de travail : contexte, compression et lost-in-the-middle <a class="header-anchor" href="#memoire-de-travail-contexte-compression-et-lost-in-the-middle" aria-label="Permalink to &quot;Mémoire de travail : contexte, compression et lost-in-the-middle&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Notion</th><th>Ce qu’il faut savoir</th></tr></thead><tbody><tr><td><strong>Context Window</strong></td><td>Quantité de tokens vue en une requête : prompt + historique + pièces jointes + réponse. Claude Sonnet 4.6 va jusqu’à 1M tokens, mais précision et coût se dégradent bien avant ce plafond.</td></tr><tr><td><strong>Context Compression</strong></td><td>Quand la fenêtre sature (longue session Claude Code, Cowork…), les anciens échanges sont résumés automatiquement. On garde l’essentiel, on perd les détails.</td></tr><tr><td><strong>Lost in the middle</strong></td><td>L’attention n’est pas uniforme : le modèle retient mieux le début et la fin (courbe en U).</td></tr></tbody></table><p>Bonnes pratiques :</p><ul><li>Instructions critiques <strong>au début ET rappelées à la fin</strong> du prompt.</li><li>Documents : les plus importants en premier.</li><li>Découper les longues missions en étapes courtes.</li><li>Sur un travail long : « résume ce qu’on a fait, et continue ».</li></ul><h3 id="agentique" tabindex="-1">Agentique <a class="header-anchor" href="#agentique" aria-label="Permalink to &quot;Agentique&quot;">​</a></h3><p>L’outil (le programme autour du LLM) reçoit la requête, signale au LLM les agents disponibles (recherche…), exécute les appels demandés et renvoie les résultats au LLM : <strong>plusieurs requêtes successives</strong> pour une seule question. Trois familles d’accès : RAG et données locales, outils via <strong>MCP</strong>, réalisation d’actions.</p><h3 id="embeddings-et-rag" tabindex="-1">Embeddings et RAG <a class="header-anchor" href="#embeddings-et-rag" aria-label="Permalink to &quot;Embeddings et RAG&quot;">​</a></h3><ul><li><strong>Embeddings</strong> : un texte est projeté en <strong>vecteur numérique</strong> dans un espace à plusieurs centaines de dimensions. Deux textes proches par le sens se retrouvent proches dans l’espace, même sans mots communs : « bug en prod » ≈ « incident critique » ≈ « panne système ».</li><li><strong>RAG</strong> (Retrieval-Augmented Generation) : répondre à partir de <strong>vos documents</strong> sans les avoir appris.</li></ul><table tabindex="0"><thead><tr><th>Étape</th><th>Ce qui se passe</th></tr></thead><tbody><tr><td>1. Indexation</td><td>Les documents sont découpés en chunks, transformés en embeddings, rangés dans une base vectorielle</td></tr><tr><td>2. Retrieval</td><td>Pour une question, on récupère les chunks les plus proches sémantiquement</td></tr><tr><td>3. Augmentation</td><td>Les chunks retrouvés sont injectés dans le prompt comme contexte</td></tr></tbody></table><blockquote><p>C’est la parade n°1 contre les <strong>hallucinations</strong>. Claude : les Projects font du RAG léger automatiquement ; au-delà (10k+ docs), un connecteur MCP vers une vector DB.</p></blockquote><h3 id="l-ecosysteme-et-les-regles-d-utilisation" tabindex="-1">L’écosystème et les règles d’utilisation <a class="header-anchor" href="#l-ecosysteme-et-les-regles-d-utilisation" aria-label="Permalink to &quot;L&#39;écosystème et les règles d&#39;utilisation&quot;">​</a></h3><ul><li><strong>Assistants bureautique</strong> (intégrés aux applications), <strong>assistants de dév</strong> (Dev / Sec / Ops), <strong>modèles et Cloud</strong> (on-prem ou via des providers).</li><li>Toujours utiliser une IA générative <strong>contractualisée</strong> par votre entreprise : pas de réutilisation des données pour l’entraînement (<strong>Zero-Data Retention</strong>) et confidentialité garantie. Pour tout autre outil : demander à la <strong>DSI</strong>.</li><li><strong>Shadow AI</strong> : un outil non contractualisé expose vos données à leur réutilisation.</li><li><strong>Nos postures comptent</strong> : individu → équipe → entreprise ; l’humain reste au centre ; une utilisation à bon escient, pas masquée, critique.</li></ul><h2 id="2-l-art-du-prompt-avec-claude" tabindex="-1">2. L’art du prompt avec Claude <a class="header-anchor" href="#2-l-art-du-prompt-avec-claude" aria-label="Permalink to &quot;2. L&#39;art du prompt avec Claude&quot;">​</a></h2><h3 id="les-reglages-de-claude" tabindex="-1">Les réglages de Claude <a class="header-anchor" href="#les-reglages-de-claude" aria-label="Permalink to &quot;Les réglages de Claude&quot;">​</a></h3><ul><li><strong>Choisir le modèle</strong> (menu en haut du chat) : Opus pour raisonner, Sonnet par défaut, Haiku pour aller vite.</li><li><strong>Activer des capacités</strong> : recherche web, exécution de code, lecture de fichiers joints (PDF, xlsx, images), connecteurs MCP (Drive, Slack, Asana…), génération d’Artifacts.</li><li><strong>Ranger les conversations par Projects</strong> : un historique + des fichiers + une instruction persistante.</li><li>Garder en tête le <strong>coût</strong> et la <strong>sobriété</strong>.</li></ul><h3 id="le-prompt-structure" tabindex="-1">Le prompt structuré <a class="header-anchor" href="#le-prompt-structure" aria-label="Permalink to &quot;Le prompt structuré&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Élément</th><th>Exemple</th></tr></thead><tbody><tr><td><strong>Persona</strong></td><td>« Tu es un expert commercial en IT… »</td></tr><tr><td><strong>Tâche</strong></td><td>« Tu dois produire une trame de réponse pour cet appel d’offre… »</td></tr><tr><td><strong>Format</strong></td><td>« …au format Markdown, ton professionnel, sans réexpliquer les mots de l’appel d’offre… »</td></tr><tr><td><strong>Contexte</strong></td><td>le client, l’évènement, le mail contenant…</td></tr></tbody></table><blockquote><p><strong>Style</strong> : Claude abuse du gras et des listes. Utiliser des <strong>balises XML</strong> (<code>&lt;contexte&gt;</code>, <code>&lt;tache&gt;</code>, <code>&lt;exemple&gt;</code>) pour isoler proprement les blocs du prompt.</p></blockquote><h3 id="styles-et-projects" tabindex="-1">Styles et Projects <a class="header-anchor" href="#styles-et-projects" aria-label="Permalink to &quot;Styles et Projects&quot;">​</a></h3><ul><li><strong>Styles</strong> : ajuster le ton et le format (concis, formel, explicatif…), présets ou personnalisés.</li><li><strong>Projects</strong> : un espace de travail persistant (documents de référence, instructions, historique), partageable au sein d’une <strong>Team Anthropic</strong>.</li></ul><h2 id="3-outils-usages-et-mise-en-pratique" tabindex="-1">3. Outils, usages et mise en pratique <a class="header-anchor" href="#3-outils-usages-et-mise-en-pratique" aria-label="Permalink to &quot;3. Outils, usages et mise en pratique&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Outil</th><th>Ce qu’il fait</th></tr></thead><tbody><tr><td><strong>Artefacts</strong></td><td>Un livrable (document, tableau, page HTML, mini-app) ouvert dans un panneau à droite : édition itérative, export Word / Excel / PDF / code, persistance</td></tr><tr><td><strong>Claude Opus 4.7</strong></td><td>Le raisonneur profond : tâches complexes, analyses longues. Plus lent, plus cher</td></tr><tr><td><strong>Claude Sonnet 4.6</strong></td><td>Le couteau suisse, par défaut : 90 % des usages</td></tr><tr><td><strong>Claude Haiku 4.5</strong></td><td>Le rapide : tâches simples et volumineuses. Quasi-instantané, très bon marché</td></tr><tr><td><strong>Connecteurs MCP</strong></td><td>Protocole standard pour lire / écrire dans un outil externe (Drive, Slack, Asana, Jira, GitHub…)</td></tr><tr><td><strong>Claude in Chrome</strong> (beta)</td><td>Pilote vos onglets : formulaire, extraction, navigation</td></tr><tr><td><strong>Claude in Excel</strong> (beta)</td><td>Agent tableur : nettoyer, formules, rapport</td></tr><tr><td><strong>Cowork</strong></td><td>Agent de bureau avec accès contrôlé à un dossier local et au navigateur, pour les profils non techniques</td></tr><tr><td><strong>Claude Code</strong></td><td>Agent dans le terminal qui pilote un dépôt comme un développeur, pour les profils tech</td></tr></tbody></table><ul><li><strong>Pensée adaptative</strong> : sur Opus et Sonnet, un toggle laisse Claude « réfléchir avant de répondre ».</li><li><strong>Skill</strong> : un dossier qui emballe un savoir-faire reproductible, un <code>SKILL.md</code> (mode d’emploi) + des fichiers de support, chargé <strong>automatiquement</strong> quand il correspond à la demande. Structure minimale : un nom + une description (quand l’activer), un <code>SKILL.md</code> (étapes, règles, pièges), en option des templates / checklists.</li><li><strong>Project vs Skill</strong> : un Project porte un <strong>contexte</strong> (« tout sur le client X »), une Skill porte une <strong>compétence</strong> (« comment rédiger un CR chez nous »). Les deux se combinent.</li><li><strong>Cowork vs chat</strong> : Cowork a les mains dans vos fichiers et vos applis ; le chat se limite aux pièces jointes uploadées.</li><li><strong>Claude Code</strong> : naviguer dans un dépôt, écrire du code sur plusieurs fichiers, lancer les tests, interagir avec Git, ouvrir une PR, appeler des MCP, charger des Skills, travailler en <strong>mode plan</strong> ou en exécution directe.</li></ul><blockquote><p>Chaque intégration doit être validée par la <strong>DSI</strong> : pas de données client sans feu vert.</p></blockquote><h2 id="4-synthese-les-4-rails-d-une-ia-utile" tabindex="-1">4. Synthèse : les 4 rails d’une IA utile <a class="header-anchor" href="#4-synthese-les-4-rails-d-une-ia-utile" aria-label="Permalink to &quot;4. Synthèse : les 4 rails d&#39;une IA utile&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Rail</th><th>Ce qu’on fait</th></tr></thead><tbody><tr><td><strong>Contexte</strong></td><td>Projects pour persister, pièces jointes pour ponctuel, RAG pour la masse</td></tr><tr><td><strong>Instructions</strong></td><td>Persona, Tâche, Format, Contexte. Balises XML pour structurer. Critiques en haut et en bas du prompt</td></tr><tr><td><strong>Modèle et réglages</strong></td><td>Haiku pour la vitesse, Sonnet par défaut, Opus pour raisonner. Température basse pour le code, haute pour la créa</td></tr><tr><td><strong>Vérification</strong></td><td>Citations (RAG), relire le diff (Claude Code), ne jamais oublier l’hallucination. Règle DSI sur les données sensibles</td></tr></tbody></table><blockquote><p>L’écosystème change constamment : le plus important est de <strong>continuer à pratiquer</strong>.</p></blockquote>',41)])])}const g=t(o,[["render",a]]);export{m as __pageData,g as default};
